<?php $title='Customers';require __DIR__.'/../includes/header.php';require_login('admin');require __DIR__.'/../config/database.php';if(isset($_GET['action'],$_GET['id'])){$action=$_GET['action'];$status=$action==='disable'?'disabled':($action==='activate'?'active':null);if($status){$pdo->prepare("UPDATE users SET status=? WHERE id=? AND role='customer'")->execute([$status,(int)$_GET['id']]);}redirect(BASE_URL.'admin/customers.php');}$rows=$pdo->query("SELECT id,name,email,phone,status,created_at FROM users WHERE role='customer' ORDER BY created_at DESC")->fetchAll();?>
<section class="section-pad"><div class="container"><h1 class="fw-bold mb-4">Customers</h1><div class="card border-0 shadow-sm rounded-4 p-3"><div class="table-responsive"><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Status</th><th>Joined</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['phone'])?></td><td><?=e($r['status'])?></td><td><?=e($r['created_at'])?></td><td><?php if($r['status']==='active'):?><a class="btn btn-sm btn-outline-danger" href="?action=disable&id=<?=$r['id']?>">Disable</a><?php elseif($r['status']==='disabled'):?><a class="btn btn-sm btn-outline-success" href="?action=activate&id=<?=$r['id']?>">Activate</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></div></section><?php require __DIR__.'/../includes/footer.php'; ?>